import React, { useState, useEffect, useCallback } from "react";
import PrintChallan from "../components/PrintChallan";

const API = "http://localhost:4000";
const token = () => localStorage.getItem("dhown_token");
const h = () => ({ "Content-Type": "application/json", Authorization: `Bearer ${token()}` });
const fmtKg = v => v != null ? parseFloat(v).toFixed(3) : "—";
const today = () => new Date().toISOString().slice(0, 10);

const inp = { width: "100%", background: "#0a1828", border: "1px solid #1e3a5f", borderRadius: 5, padding: "7px 10px", color: "#e2e8f0", fontSize: 13 };
const lbl = { color: "#7da2d6", fontSize: 11, marginBottom: 3, display: "block", textTransform: "uppercase", letterSpacing: 0.5 };

const emptyRow = () => ({ lot_id: "", issued_kg: "" });
const emptyForm = () => ({ machine_id: "", issued_by: "", received_by: "", issue_date: today(), notes: "" });

export default function YarnIssue() {
  const [issues,      setIssues]      = useState([]);
  const [selected,    setSelected]    = useState(null);
  const [printing,    setPrinting]    = useState(false);
  const [loading,     setLoading]     = useState(true);
  const [statusFilter,setStatusFilter]= useState("");
  const [showNew,     setShowNew]     = useState(false);
  const [saving,      setSaving]      = useState(false);
  const [error,       setError]       = useState("");

  const [machines,    setMachines]    = useState([]);
  const [yarns,       setYarns]       = useState([]);  // IN_STORE lots

  const [form,    setForm]    = useState(emptyForm());
  const [rows,    setRows]    = useState([emptyRow()]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const url = `${API}/api/yarn-issues${statusFilter ? `?status=${statusFilter}` : ""}`;
      const r = await fetch(url, { headers: h() });
      setIssues(await r.json());
    } catch {}
    setLoading(false);
  }, [statusFilter]);

  const loadMeta = useCallback(async () => {
    try {
      const [m, y] = await Promise.all([
        fetch(`${API}/api/machines`, { headers: h() }).then(r => r.json()),
        fetch(`${API}/api/yarn-store?status=IN_STORE`, { headers: h() }).then(r => r.json()),
      ]);
      setMachines(Array.isArray(m) ? m : []);
      setYarns(Array.isArray(y) ? y : []);
    } catch {}
  }, []);

  useEffect(() => { load(); }, [load]);

  const loadDetail = async (id) => {
    const r = await fetch(`${API}/api/yarn-issues/${id}`, { headers: h() });
    setSelected(await r.json());
  };

  const openNew = () => {
    loadMeta();
    setForm(emptyForm());
    setRows([emptyRow()]);
    setError("");
    setShowNew(true);
  };

  const updateRow = (idx, field, value) => {
    setRows(prev => prev.map((r, i) => i !== idx ? r : { ...r, [field]: value }));
  };

  const addRow = () => setRows(prev => [...prev, emptyRow()]);
  const removeRow = (idx) => setRows(prev => prev.length === 1 ? prev : prev.filter((_, i) => i !== idx));

  const submit = async (e) => {
    e.preventDefault();
    setError("");
    const items = rows.filter(r => r.lot_id && r.issued_kg);
    if (!items.length) { setError("Add at least one yarn lot with quantity"); return; }

    // Validate stock
    for (const row of items) {
      const lot = yarns.find(l => String(l.lot_id) === String(row.lot_id));
      if (lot && parseFloat(row.issued_kg) > parseFloat(lot.current_stock_kg)) {
        setError(`Lot ${lot.lot_number}: only ${parseFloat(lot.current_stock_kg).toFixed(3)} kg available`);
        return;
      }
    }

    const machine = machines.find(m => String(m.machine_id) === String(form.machine_id));
    const payload = {
      ...form,
      machine_name: machine?.name || machine?.machine_name || form.machine_id,
      items: items.map(r => {
        const lot = yarns.find(l => String(l.lot_id) === String(r.lot_id));
        return {
          lot_id: parseInt(r.lot_id),
          lot_number: lot?.lot_number,
          yarn_type: lot?.yarn_type,
          color: lot?.color,
          available_kg: lot?.current_stock_kg,
          issued_kg: parseFloat(r.issued_kg),
        };
      }),
    };

    setSaving(true);
    try {
      const r = await fetch(`${API}/api/yarn-issues`, { method: "POST", headers: h(), body: JSON.stringify(payload) });
      const j = await r.json();
      if (!r.ok) { setError(j.error || "Failed to save"); setSaving(false); return; }
      setShowNew(false);
      await load();
      loadDetail(j.issue_id || j.id);
    } catch (err) { setError("Network error"); }
    setSaving(false);
  };

  const totalIssued = rows.reduce((s, r) => s + parseFloat(r.issued_kg || 0), 0);

  const STATUS_COLORS = { ISSUED: "#f59e0b", CLOSED: "#10b981", PARTIAL: "#60a5fa" };

  return (
    <>
    <div style={{ padding: 20, color: "#e2e8f0", fontFamily: "Inter, sans-serif" }}>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <div>
          <h2 style={{ margin: 0, color: "#f4ae1f", fontSize: 24 }}>Yarn Issue</h2>
          <div style={{ color: "#7da2d6", fontSize: 12, marginTop: 2 }}>Issue yarn lots to machines · track consumption</div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {[["", "All"], ["ISSUED", "Issued"], ["CLOSED", "Closed"]].map(([s, label]) => (
            <button key={s} onClick={() => setStatusFilter(s)}
              style={{ padding: "6px 14px", borderRadius: 5, border: "1px solid #1e3a5f", cursor: "pointer", fontSize: 12,
                background: statusFilter === s ? "#f4ae1f" : "#0a1828", color: statusFilter === s ? "#081426" : "#e2e8f0" }}>
              {label}
            </button>
          ))}
          <button onClick={openNew}
            style={{ background: "#f4ae1f", color: "#081426", border: "none", borderRadius: 6, padding: "8px 18px", fontWeight: "bold", cursor: "pointer", fontSize: 13 }}>
            + Issue Yarn
          </button>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "340px 1fr", gap: 20 }}>

        {/* List */}
        <div style={{ overflowY: "auto", maxHeight: "calc(100vh - 140px)" }}>
          {loading ? (
            <div style={{ color: "#7da2d6", padding: 40, textAlign: "center" }}>Loading...</div>
          ) : issues.length === 0 ? (
            <div style={{ color: "#7da2d6", padding: 60, textAlign: "center" }}>No yarn issues yet.</div>
          ) : issues.map(iss => (
            <div key={iss.issue_id} onClick={() => loadDetail(iss.issue_id)}
              style={{ background: selected?.issue_id === iss.issue_id ? "#0d2040" : "#0a1828",
                border: `1px solid ${selected?.issue_id === iss.issue_id ? "#f4ae1f" : "#1e3a5f"}`,
                borderLeft: `4px solid ${STATUS_COLORS[iss.status] || "#1e3a5f"}`,
                borderRadius: 8, padding: "12px 14px", marginBottom: 8, cursor: "pointer" }}>
              <div style={{ color: "#f4ae1f", fontWeight: "bold", fontSize: 13, fontFamily: "monospace" }}>{iss.issue_number}</div>
              <div style={{ color: "#e2e8f0", fontSize: 13, marginTop: 2 }}>{iss.machine_name || `Machine #${iss.machine_id}`}</div>
              <div style={{ color: "#7da2d6", fontSize: 11, marginTop: 3, display: "flex", gap: 10 }}>
                <span>📅 {iss.issue_date?.slice(0, 10)}</span>
                <span>📦 {iss.item_count || 0} lots</span>
                <span>⚖️ {parseFloat(iss.total_issued_kg || 0).toFixed(1)} kg</span>
              </div>
              <span style={{ marginTop: 4, display: "inline-block", background: (STATUS_COLORS[iss.status] || "#1e3a5f") + "22", color: STATUS_COLORS[iss.status] || "#7da2d6", border: `1px solid ${STATUS_COLORS[iss.status] || "#1e3a5f"}`, borderRadius: 4, padding: "2px 8px", fontSize: 10, fontWeight: 700 }}>{iss.status}</span>
            </div>
          ))}
        </div>

        {/* Detail */}
        {selected ? (
          <div style={{ background: "#0a1828", border: "1px solid #1e3a5f", borderRadius: 10, overflow: "hidden" }}>
            <div style={{ background: "#0d2040", padding: "14px 18px", borderBottom: "1px solid #1e3a5f", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ color: "#f4ae1f", fontWeight: "bold", fontSize: 16, fontFamily: "monospace" }}>{selected.issue_number}</div>
                <div style={{ color: "#e2e8f0", fontSize: 14, marginTop: 2 }}>{selected.machine_name}</div>
                <div style={{ color: "#7da2d6", fontSize: 12, marginTop: 2 }}>
                  Date: <strong style={{ color: "#cbd5e1" }}>{selected.issue_date?.slice(0, 10)}</strong> &nbsp;|&nbsp;
                  Issued by: <strong style={{ color: "#cbd5e1" }}>{selected.issued_by || "—"}</strong> &nbsp;|&nbsp;
                  Received by: <strong style={{ color: "#cbd5e1" }}>{selected.received_by || "—"}</strong>
                </div>
              </div>
              <button onClick={() => setPrinting(true)} style={{ background: "#1e3a5f", color: "#93c5fd", border: "none", padding: "6px 12px", borderRadius: 6, cursor: "pointer", fontSize: 12, fontWeight: 600 }}>🖨 Print</button>
            </div>

            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                <thead>
                  <tr style={{ background: "#0d2040", borderBottom: "1px solid #1e3a5f" }}>
                    {["Lot No.", "Yarn Type", "Colour", "Issued (kg)", "Returned (kg)", "Consumed (kg)", "Supplier Lot", "Location"].map(col => (
                      <th key={col} style={{ padding: "8px 10px", textAlign: "left", color: "#64748b", fontWeight: 600, fontSize: 10, textTransform: "uppercase", letterSpacing: 0.5, whiteSpace: "nowrap" }}>{col}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {(selected.items || []).map((item, i) => (
                    <tr key={item.item_id} style={{ background: i % 2 === 0 ? "#081424" : "#0a1828", borderBottom: "1px solid #0f2040" }}>
                      <td style={{ padding: "9px 10px", fontFamily: "monospace", color: "#f4ae1f", fontWeight: 700 }}>{item.lot_number}</td>
                      <td style={{ padding: "9px 10px", color: "#e2e8f0", fontWeight: 600 }}>{item.yarn_type}</td>
                      <td style={{ padding: "9px 10px", color: "#cbd5e1" }}>{item.color}</td>
                      <td style={{ padding: "9px 10px", color: "#fbbf24", textAlign: "right", fontWeight: 700 }}>{fmtKg(item.issued_kg)}</td>
                      <td style={{ padding: "9px 10px", color: "#94a3b8", textAlign: "right" }}>{parseFloat(item.returned_kg || 0) > 0 ? fmtKg(item.returned_kg) : "—"}</td>
                      <td style={{ padding: "9px 10px", color: "#f59e0b", textAlign: "right", fontWeight: 700 }}>{fmtKg(item.consumed_kg || item.issued_kg)}</td>
                      <td style={{ padding: "9px 10px", color: "#94a3b8", fontFamily: "monospace", fontSize: 11 }}>{item.supplier_lot_no || "—"}</td>
                      <td style={{ padding: "9px 10px", color: "#94a3b8" }}>{item.location || "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {selected.notes && (
              <div style={{ margin: "14px 16px", background: "#0d1b2a", borderRadius: 6, padding: "8px 12px", fontSize: 12, color: "#94a3b8" }}>
                <span style={{ color: "#64748b", fontSize: 10, textTransform: "uppercase" }}>Notes: </span>{selected.notes}
              </div>
            )}
          </div>
        ) : (
          <div style={{ background: "#0a1828", border: "1px solid #1e3a5f", borderRadius: 10, display: "flex", alignItems: "center", justifyContent: "center", color: "#475569", fontSize: 14 }}>
            Select a yarn issue to view details
          </div>
        )}
      </div>

      {/* ── New Issue — full-screen single entry ── */}
      {showNew && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", zIndex: 1000, overflowY: "auto", padding: "20px 0" }}>
          <form onSubmit={submit} style={{ background: "#081426", border: "1px solid #f4ae1f", borderRadius: 10, width: "min(98vw, 1050px)", margin: "0 auto", padding: 24 }}>

            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
              <div>
                <h3 style={{ color: "#f4ae1f", margin: 0, fontSize: 18 }}>Issue Yarn to Machine</h3>
                <div style={{ color: "#7da2d6", fontSize: 12, marginTop: 2 }}>Select machine, add all lots and quantities — save in one go</div>
              </div>
              <button type="button" onClick={() => setShowNew(false)}
                style={{ background: "transparent", border: "1px solid #1e3a5f", color: "#94a3b8", borderRadius: 6, padding: "6px 14px", cursor: "pointer", fontSize: 13 }}>✕ Cancel</button>
            </div>

            {error && <div style={{ background: "#ef444422", border: "1px solid #ef4444", borderRadius: 5, padding: "8px 12px", color: "#ef4444", fontSize: 13, marginBottom: 14 }}>{error}</div>}

            {/* Header */}
            <div style={{ background: "#0a1828", border: "1px solid #1e3a5f", borderRadius: 8, padding: "14px 16px", marginBottom: 16 }}>
              <div style={{ color: "#64748b", fontSize: 10, textTransform: "uppercase", letterSpacing: 1, marginBottom: 12, fontWeight: 700 }}>Issue Details</div>
              <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr 1fr 1fr", gap: 12 }}>
                <div>
                  <label style={lbl}>Machine *</label>
                  <select required value={form.machine_id} onChange={e => setForm(f => ({ ...f, machine_id: e.target.value }))} style={inp}>
                    <option value="">— Select machine —</option>
                    {machines.map(m => <option key={m.machine_id} value={m.machine_id}>{m.name || m.machine_name || m.machine_id} {m.fabric ? `(${m.fabric})` : ""}</option>)}
                  </select>
                </div>
                <div>
                  <label style={lbl}>Issue Date *</label>
                  <input type="date" required value={form.issue_date} onChange={e => setForm(f => ({ ...f, issue_date: e.target.value }))} style={inp} />
                </div>
                <div>
                  <label style={lbl}>Issued By</label>
                  <input value={form.issued_by} onChange={e => setForm(f => ({ ...f, issued_by: e.target.value }))} style={inp} placeholder="Store incharge" />
                </div>
                <div>
                  <label style={lbl}>Received By</label>
                  <input value={form.received_by} onChange={e => setForm(f => ({ ...f, received_by: e.target.value }))} style={inp} placeholder="Machine operator" />
                </div>
              </div>
              <div style={{ marginTop: 10 }}>
                <label style={lbl}>Notes</label>
                <input value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} style={inp} placeholder="Any instructions (optional)" />
              </div>
            </div>

            {/* Lots table */}
            <div style={{ background: "#0a1828", border: "1px solid #1e3a5f", borderRadius: 8, padding: "14px 16px", marginBottom: 16 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <div style={{ color: "#64748b", fontSize: 10, textTransform: "uppercase", letterSpacing: 1, fontWeight: 700 }}>Yarn Lots to Issue</div>
                <button type="button" onClick={addRow}
                  style={{ background: "#1e3a5f", color: "#f4ae1f", border: "1px solid #f4ae1f", borderRadius: 5, padding: "4px 12px", fontSize: 12, cursor: "pointer", fontWeight: 600 }}>
                  + Add Row
                </button>
              </div>

              <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
                  <thead>
                    <tr style={{ background: "#0d2040" }}>
                      {["#", "Yarn Lot (from Yarn Store)", "Yarn Type", "Available (kg)", "Issue Qty (kg)", ""].map(col => (
                        <th key={col} style={{ padding: "7px 8px", textAlign: "left", color: "#64748b", fontWeight: 600, fontSize: 10, textTransform: "uppercase", letterSpacing: 0.4, whiteSpace: "nowrap", borderBottom: "1px solid #1e3a5f" }}>{col}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row, idx) => {
                      const lot = yarns.find(l => String(l.lot_id) === String(row.lot_id));
                      const overStock = lot && parseFloat(row.issued_kg) > parseFloat(lot.current_stock_kg);
                      return (
                        <tr key={idx} style={{ borderBottom: "1px solid #0f2040" }}>
                          <td style={{ padding: "6px 8px", color: "#64748b", width: 28 }}>{idx + 1}</td>
                          <td style={{ padding: "4px 6px", minWidth: 220 }}>
                            <select value={row.lot_id} onChange={e => updateRow(idx, "lot_id", e.target.value)} style={{ ...inp, padding: "5px 6px", fontSize: 12 }}>
                              <option value="">— Select lot —</option>
                              {yarns.map(l => (
                                <option key={l.lot_id} value={l.lot_id}>
                                  {l.lot_number} — {l.yarn_type} {l.color} ({parseFloat(l.current_stock_kg).toFixed(1)} kg)
                                </option>
                              ))}
                            </select>
                          </td>
                          <td style={{ padding: "6px 8px", color: "#a5b4fc", whiteSpace: "nowrap" }}>{lot?.yarn_type || "—"}</td>
                          <td style={{ padding: "6px 8px", color: "#34d399", fontWeight: 600 }}>
                            {lot ? fmtKg(lot.current_stock_kg) : "—"}
                          </td>
                          <td style={{ padding: "4px 6px", width: 110 }}>
                            <input type="number" step="0.001" min="0.001" value={row.issued_kg}
                              onChange={e => updateRow(idx, "issued_kg", e.target.value)}
                              style={{ ...inp, padding: "5px 6px", fontSize: 12, border: `1px solid ${overStock ? "#ef4444" : "#1e3a5f"}` }}
                              placeholder="0.000" />
                            {overStock && <div style={{ fontSize: 10, color: "#ef4444", marginTop: 1 }}>exceeds stock</div>}
                          </td>
                          <td style={{ padding: "4px 6px", width: 28 }}>
                            <button type="button" onClick={() => removeRow(idx)}
                              style={{ background: "transparent", border: "none", color: "#ef4444", cursor: "pointer", fontSize: 16 }}>×</button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot>
                    <tr style={{ background: "#0d2040", borderTop: "2px solid #1e3a5f", fontWeight: 700 }}>
                      <td colSpan={3} style={{ padding: "7px 8px", color: "#94a3b8", fontSize: 11 }}>TOTAL — {rows.filter(r => r.lot_id).length} lot(s)</td>
                      <td></td>
                      <td style={{ padding: "7px 8px", color: "#fbbf24" }}>{totalIssued > 0 ? totalIssued.toFixed(3) + " kg" : "—"}</td>
                      <td></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>

            <div style={{ display: "flex", gap: 12, justifyContent: "flex-end" }}>
              <button type="button" onClick={addRow}
                style={{ background: "transparent", border: "1px solid #1e3a5f", color: "#7da2d6", borderRadius: 6, padding: "10px 20px", cursor: "pointer", fontSize: 13 }}>
                + Add Another Lot
              </button>
              <button type="submit" disabled={saving}
                style={{ background: saving ? "#7a6010" : "#f4ae1f", color: "#081426", border: "none", borderRadius: 6, padding: "10px 32px", fontWeight: "bold", cursor: "pointer", fontSize: 14 }}>
                {saving ? "Saving..." : `✓ Issue Yarn (${rows.filter(r => r.lot_id && r.issued_kg).length} lots · ${totalIssued.toFixed(2)} kg)`}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>

    {printing && selected && (
      <PrintChallan type="YARN_ISSUE" data={selected} onClose={() => setPrinting(false)} />
    )}
    </>
  );
}
