import React, { useState, useRef } from "react";

const API = "http://localhost:4000";
const h = () => ({ "Content-Type": "application/json", Authorization: `Bearer ${localStorage.getItem("dhown_token")}` });

const STATUS_COLOR = {
  OPEN: "#22c55e", CLOSED: "#f59e0b", APPROVED: "#60a5fa",
  GREIGE: "#a78bfa", IN_BATCH: "#f59e0b", SENT_OUT: "#6366f1",
  FINISHED: "#10b981", DISPATCHED: "#22c55e",
};

const STEPS = [
  { key: "grn",          label: "Raw Material",    icon: "📥", color: "#6366f1" },
  { key: "yarnLot",      label: "Yarn Lot",        icon: "🧵", color: "#8b5cf6" },
  { key: "yarnIssue",    label: "Yarn Issue",      icon: "🚀", color: "#a78bfa" },
  { key: "roll",         label: "Roll Production", icon: "🧶", color: "#f4ae1f" },
  { key: "batch",        label: "Batching",        icon: "📦", color: "#f59e0b" },
  { key: "challan",      label: "Dye / Finish",    icon: "🎨", color: "#ec4899" },
  { key: "receipt",      label: "Receipt",         icon: "📋", color: "#14b8a6" },
  { key: "finishing",    label: "QA / Finishing",  icon: "✔️", color: "#10b981" },
  { key: "finishedGoods", label: "Finished Goods", icon: "✅", color: "#22c55e" },
  { key: "dispatch",     label: "Dispatch",        icon: "📤", color: "#3b82f6" },
];

export default function Traceability() {
  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [chain, setChain] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const debounce = useRef(null);

  const search = async (val) => {
    setQuery(val);
    clearTimeout(debounce.current);
    if (!val || val.length < 3) { setSuggestions([]); return; }
    debounce.current = setTimeout(async () => {
      const r = await fetch(`${API}/api/traceability?q=${encodeURIComponent(val)}`, { headers: h() });
      setSuggestions(await r.json());
    }, 300);
  };

  const load = async (roll_id) => {
    setLoading(true); setError(""); setChain(null); setSuggestions([]);
    setQuery(roll_id);
    try {
      const r = await fetch(`${API}/api/traceability/${encodeURIComponent(roll_id)}`, { headers: h() });
      const j = await r.json();
      if (!r.ok) { setError(j.error || "Not found"); setLoading(false); return; }
      setChain(j);
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  const field = (label, value, color = "#e2e8f0") => value ? (
    <div style={{ marginBottom: 6 }}>
      <span style={{ color: "#7da2d6", fontSize: 11 }}>{label}: </span>
      <span style={{ color, fontWeight: 500, fontSize: 13 }}>{value}</span>
    </div>
  ) : null;

  const StepCard = ({ step, data, children }) => {
    const active = !!data;
    return (
      <div style={{ display: "flex", gap: 0, alignItems: "stretch" }}>
        {/* Connector line + dot */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: 40, flexShrink: 0 }}>
          <div style={{ width: 3, flex: 1, background: active ? step.color : "#1e3a5f", minHeight: 16 }} />
          <div style={{ width: 32, height: 32, borderRadius: "50%", background: active ? step.color : "#1e3a5f", border: `3px solid ${active ? step.color : "#2d4a6f"}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14, flexShrink: 0, zIndex: 1 }}>
            {active ? step.icon : "○"}
          </div>
          <div style={{ width: 3, flex: 1, background: active ? step.color : "#1e3a5f", minHeight: 16 }} />
        </div>

        {/* Card */}
        <div style={{ flex: 1, margin: "8px 0 8px 12px", background: active ? "#0d1b2a" : "#081426", border: `1px solid ${active ? step.color + "55" : "#1e3a5f"}`, borderRadius: 8, padding: active ? "14px 16px" : "10px 16px", opacity: active ? 1 : 0.45 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: active ? 8 : 0 }}>
            <span style={{ color: active ? step.color : "#4a5568", fontWeight: "bold", fontSize: 13 }}>{step.label}</span>
            {!active && <span style={{ color: "#4a5568", fontSize: 11 }}>— not linked</span>}
          </div>
          {active && children}
        </div>
      </div>
    );
  };

  const rollWs = chain?.roll?.warehouse_status;
  const rollStatus = chain?.roll?.status;

  return (
    <div style={{ padding: 20, color: "#e2e8f0", maxWidth: 900, margin: "0 auto" }}>
      <h2 style={{ margin: "0 0 6px", color: "#f4ae1f" }}>🔍 Roll Traceability</h2>
      <div style={{ color: "#7da2d6", fontSize: 13, marginBottom: 24 }}>
        Full genealogy chain: Raw Material → Production → Warehouse → Dispatch
      </div>

      {/* Search box */}
      <div style={{ position: "relative", marginBottom: 28 }}>
        <div style={{ display: "flex", gap: 10 }}>
          <input
            value={query}
            onChange={e => search(e.target.value)}
            onKeyDown={e => e.key === "Enter" && query && load(query)}
            placeholder="Search roll ID (e.g. SJ01-C40-240701-D-001)..."
            style={{ flex: 1, background: "#0d1b2a", border: "1px solid #f4ae1f", borderRadius: 8, padding: "12px 16px", color: "#e2e8f0", fontSize: 14 }}
          />
          <button onClick={() => query && load(query)} disabled={loading}
            style={{ background: "#f4ae1f", color: "#081426", border: "none", borderRadius: 8, padding: "12px 24px", fontWeight: "bold", cursor: "pointer", fontSize: 14 }}>
            {loading ? "..." : "Trace"}
          </button>
        </div>

        {/* Autocomplete */}
        {suggestions.length > 0 && (
          <div style={{ position: "absolute", top: "100%", left: 0, right: 60, background: "#0d1b2a", border: "1px solid #1e3a5f", borderRadius: 8, zIndex: 100, marginTop: 4, overflow: "hidden" }}>
            {suggestions.map(s => (
              <div key={s.roll_id} onClick={() => load(s.roll_id)}
                style={{ padding: "10px 16px", cursor: "pointer", borderBottom: "1px solid #1e3a5f", display: "flex", justifyContent: "space-between" }}
                onMouseEnter={e => e.currentTarget.style.background = "#1e3a5f"}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <span style={{ color: "#f4ae1f", fontWeight: "bold", fontSize: 13 }}>{s.roll_id}</span>
                <span style={{ color: "#7da2d6", fontSize: 12 }}>{s.machine_name} · {s.warehouse_status || s.status} · {parseFloat(s.actual_weight_kg || 0).toFixed(1)}kg</span>
              </div>
            ))}
          </div>
        )}
      </div>

      {error && <div style={{ background: "#ef444422", border: "1px solid #ef4444", borderRadius: 8, padding: "12px 16px", color: "#ef4444", marginBottom: 20 }}>{error}</div>}

      {chain && (
        <>
          {/* Roll header */}
          <div style={{ background: "#0d1b2a", border: `2px solid #f4ae1f`, borderRadius: 10, padding: "16px 20px", marginBottom: 24 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ color: "#f4ae1f", fontWeight: "bold", fontSize: 20 }}>{chain.roll.roll_id}</div>
                <div style={{ color: "#7da2d6", fontSize: 13, marginTop: 2 }}>{chain.roll.machine_name} · {chain.roll.operator_name || "No operator"}</div>
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
                <span style={{ background: (STATUS_COLOR[rollStatus] || "#7da2d6") + "22", color: STATUS_COLOR[rollStatus] || "#7da2d6", border: `1px solid ${STATUS_COLOR[rollStatus] || "#7da2d6"}`, borderRadius: 4, padding: "3px 10px", fontSize: 12 }}>{rollStatus}</span>
                {rollWs && <span style={{ background: (STATUS_COLOR[rollWs] || "#7da2d6") + "22", color: STATUS_COLOR[rollWs] || "#7da2d6", border: `1px solid ${STATUS_COLOR[rollWs] || "#7da2d6"}`, borderRadius: 4, padding: "3px 10px", fontSize: 12 }}>WH: {rollWs}</span>}
              </div>
            </div>
            <div style={{ display: "flex", gap: 24, marginTop: 12, flexWrap: "wrap" }}>
              {[["Weight", `${parseFloat(chain.roll.actual_weight_kg || 0).toFixed(2)} kg`],
                ["Shift", chain.roll.shift === "D" ? "☀ Day" : "🌙 Night"],
                ["Fabric", chain.roll.fabric_type || "—"],
                ["Closed", chain.roll.closed_at ? new Date(chain.roll.closed_at).toLocaleString("en-IN") : "—"],
                ["Approved", chain.roll.approved_at ? new Date(chain.roll.approved_at).toLocaleString("en-IN") : "—"],
              ].map(([l, v]) => (
                <div key={l}><div style={{ color: "#7da2d6", fontSize: 10 }}>{l}</div><div style={{ fontSize: 13 }}>{v}</div></div>
              ))}
              {chain.roll.qr_image && (
                <img src={chain.roll.qr_image} alt="QR" title="Click to print" style={{ width: 56, height: 56, cursor: "pointer", marginLeft: "auto" }}
                  onClick={() => { const w = window.open(); w.document.write(`<img src="${chain.roll.qr_image}" style="width:280px"/><p style="font-family:monospace;font-size:16px;margin-top:8px">${chain.roll.roll_id}</p>`); }} />
              )}
            </div>
          </div>

          {/* Timeline */}
          <div style={{ paddingLeft: 4 }}>
            <StepCard step={STEPS[0]} data={chain.grn}>
              {field("GRN Number", chain.grn?.grn_number, "#f4ae1f")}
              {field("Supplier", chain.grn?.supplier_name)}
              {field("Receipt Date", chain.grn?.receipt_date?.slice(0, 10))}
            </StepCard>

            <StepCard step={STEPS[1]} data={chain.yarnLot}>
              {field("Lot Number", chain.yarnLot?.lot_number, "#f4ae1f")}
              {field("Yarn Type", `${chain.yarnLot?.yarn_type}${chain.yarnLot?.count ? " · " + chain.yarnLot.count : ""}`)}
              {field("Color", chain.yarnLot?.color)}
              {field("Net Weight", `${parseFloat(chain.yarnLot?.net_weight_kg || 0).toFixed(2)} kg received`)}
              {chain.yarnLot?.qr_image && <img src={chain.yarnLot.qr_image} alt="QR" style={{ width: 40, height: 40 }} />}
            </StepCard>

            <StepCard step={STEPS[2]} data={chain.yarnIssue}>
              {field("Issue Number", chain.yarnIssue?.issue_number, "#f4ae1f")}
              {field("Issued To", chain.yarnIssue?.machine_name)}
              {field("Date", chain.yarnIssue?.issue_date?.slice(0, 10))}
              {field("Issued By", chain.yarnIssue?.issued_by)}
            </StepCard>

            <StepCard step={STEPS[3]} data={chain.roll}>
              {field("Machine", chain.roll.machine_name, "#f4ae1f")}
              {field("Operator", chain.roll.operator_name)}
              {field("Shift", chain.roll.shift === "D" ? "Day" : "Night")}
              {field("Weight", `${parseFloat(chain.roll.actual_weight_kg || 0).toFixed(2)} kg`)}
              {field("Approved By", chain.roll.supervisor_name)}
            </StepCard>

            <StepCard step={STEPS[4]} data={chain.batch}>
              {field("Batch Number", chain.batch?.batch_number, "#f4ae1f")}
              {field("Fabric Type", chain.batch?.fabric_type)}
              {field("Color", chain.batch?.color_name)}
              {field("Status", chain.batch?.status)}
              {field("Total Weight", `${parseFloat(chain.batch?.total_weight_kg || 0).toFixed(2)} kg`)}
            </StepCard>

            <StepCard step={STEPS[5]} data={chain.challan}>
              {field("Challan", chain.challan?.challan_number, "#f4ae1f")}
              {field("Vendor", chain.challan?.vendor_name)}
              {field("Job Type", chain.challan?.job_type?.replace("_", " "))}
              {field("Sent Date", chain.challan?.sent_date?.slice(0, 10))}
              {field("Sent Weight", `${parseFloat(chain.challan?.sent_weight_kg || 0).toFixed(2)} kg`)}
            </StepCard>

            <StepCard step={STEPS[6]} data={chain.receipt}>
              {field("Received Date", chain.receipt?.received_date?.slice(0, 10), "#f4ae1f")}
              {field("Received Weight", `${parseFloat(chain.receipt?.received_weight_kg || 0).toFixed(2)} kg`)}
              {field("Rejected", `${parseFloat(chain.receipt?.rejected_weight_kg || 0).toFixed(2)} kg`)}
              {field("Quality", chain.receipt?.quality_status)}
              {field("Received By", chain.receipt?.received_by)}
            </StepCard>

            <StepCard step={STEPS[7]} data={chain.finishing}>
              {field("Shade", chain.finishing?.shade, "#f4ae1f")}
              {field("GSM", chain.finishing?.gsm ? `${chain.finishing.gsm} g/m²` : null)}
              {field("Moisture", chain.finishing?.moisture_pct ? `${chain.finishing.moisture_pct}%` : null)}
              {field("Shrinkage", chain.finishing?.shrinkage_pct ? `${chain.finishing.shrinkage_pct}%` : null)}
              {field("Damage", chain.finishing?.damage_kg ? `${chain.finishing.damage_kg} kg` : null)}
              {field("QA Result", chain.finishing?.qa_passed === false ? "FAIL ✗" : "PASS ✓", chain.finishing?.qa_passed === false ? "#ef4444" : "#10b981")}
              {field("QA Notes", chain.finishing?.qa_notes)}
              {field("Finished By", chain.finishing?.finished_by)}
            </StepCard>

            <StepCard step={STEPS[8]} data={chain.finishedGoods}>
              {field("FG Status", chain.finishedGoods?.status, chain.finishedGoods?.status === "IN_STOCK" ? "#10b981" : chain.finishedGoods?.status === "HOLD" ? "#ef4444" : "#7da2d6")}
              {field("Location", chain.finishedGoods?.location)}
              {field("Weight", `${parseFloat(chain.finishedGoods?.weight_kg || 0).toFixed(2)} kg`)}
            </StepCard>

            <StepCard step={STEPS[9]} data={chain.dispatch}>
              {field("Dispatch No", chain.dispatch?.dispatch_number, "#f4ae1f")}
              {field("Customer", chain.dispatch?.customer_name)}
              {field("Dispatch Date", chain.dispatch?.dispatch_date?.slice(0, 10))}
              {field("Vehicle", chain.dispatch?.vehicle_number)}
              {field("Invoice", chain.dispatch?.invoice_number)}
              {field("Weight Dispatched", `${parseFloat(chain.dispatch?.weight_kg || 0).toFixed(2)} kg`)}
            </StepCard>
          </div>

          {/* Journey summary */}
          <div style={{ background: "#0d1b2a", border: "1px solid #1e3a5f", borderRadius: 10, padding: "14px 18px", marginTop: 16 }}>
            <div style={{ color: "#7da2d6", fontSize: 12, marginBottom: 8 }}>JOURNEY SUMMARY</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
              {STEPS.map((step, i) => {
                const keys = ["grn","yarnLot","yarnIssue","roll","batch","challan","receipt","finishing","finishedGoods","dispatch"];
                const active = !!chain[keys[i]];
                return (
                  <React.Fragment key={step.key}>
                    <span style={{ background: active ? step.color + "22" : "#081426", color: active ? step.color : "#4a5568", border: `1px solid ${active ? step.color : "#1e3a5f"}`, borderRadius: 4, padding: "3px 10px", fontSize: 11, fontWeight: active ? "bold" : 400 }}>
                      {step.icon} {step.label}
                    </span>
                    {i < STEPS.length - 1 && <span style={{ color: "#2d4a6f", fontSize: 14 }}>→</span>}
                  </React.Fragment>
                );
              })}
            </div>
          </div>
        </>
      )}

      {!chain && !loading && !error && (
        <div style={{ textAlign: "center", color: "#4a5568", marginTop: 80 }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>🔍</div>
          <div style={{ fontSize: 15, color: "#7da2d6" }}>Search for a roll ID to view its full production chain</div>
          <div style={{ fontSize: 13, marginTop: 6 }}>e.g. SJ01-C40-240701-D-001</div>
        </div>
      )}
    </div>
  );
}
